<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/config.php';

startSecureSession();
if (!isAuthenticated()) { header('Location: ' . appPath('/access/login.php')); exit; }

$cfg = appConfig();
try {
    $pdo = new PDO("mysql:host={$cfg['db_host']};dbname={$cfg['db_name']};charset={$cfg['db_charset']}", $cfg['db_user'], $cfg['db_pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
} catch (PDOException $e) { http_response_code(503); exit('Serviço temporariamente indisponível.'); }
$profile = $pdo->prepare('SELECT id, marketplace_products FROM profissionais WHERE user_id = :user_id ORDER BY id DESC LIMIT 1');
$profile->execute([':user_id' => (int) currentUserId()]);
$professional = $profile->fetch();
if (!$professional) { header('Location: ' . appPath('/secure/save_profile.php')); exit; }

function mpItems(string $raw): array {
    $decoded = json_decode($raw, true); if (!is_array($decoded)) return [];
    $items = [];
    foreach ($decoded as $position => $item) {
        if (!is_array($item) || trim((string)($item['title'] ?? '')) === '') continue;
        $legacy = trim((string)($item['image'] ?? ''));
        $images = array_values(array_filter(array_map('trim', (array)($item['images'] ?? ($legacy !== '' ? [$legacy] : [])))));
        $items[] = ['id' => preg_match('/^[a-f0-9-]{16,64}$/i', (string)($item['id'] ?? '')) ? (string)$item['id'] : bin2hex(random_bytes(12)), 'title' => mb_substr(trim((string)$item['title']), 0, 100), 'description' => mb_substr(trim((string)($item['description'] ?? '')), 0, 60), 'price' => mb_substr(trim((string)($item['price'] ?? '')), 0, 40), 'active' => !array_key_exists('active', $item) || (bool)$item['active'], 'images' => array_slice($images, 0, 4), 'order' => (int)($item['order'] ?? $position)];
    }
    usort($items, static fn($a, $b) => $a['order'] <=> $b['order']);
    foreach ($items as $i => &$item) $item['order'] = $i; unset($item);
    return $items;
}
function mpUpload(array $file): string {
    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || ($file['size'] ?? 0) > 10 * 1024 * 1024) throw new RuntimeException('Envie imagens JPG, PNG ou WEBP de até 10 MB.');
    $mime = (new finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);
    $ext = ['image/jpeg'=>'jpg', 'image/png'=>'png', 'image/webp'=>'webp'][$mime] ?? null;
    if (!$ext) throw new RuntimeException('Formato inválido. Use JPG, PNG ou WEBP.');
    $dir = __DIR__ . '/../uploads/marketplace'; if (!is_dir($dir) && !mkdir($dir, 0755, true)) throw new RuntimeException('Não foi possível preparar o armazenamento das fotos.');
    $name = bin2hex(random_bytes(16)) . '.' . $ext;
    if (!move_uploaded_file((string)$file['tmp_name'], $dir . '/' . $name)) throw new RuntimeException('Não foi possível salvar a foto.');
    return appPath('/uploads/marketplace/' . $name);
}
function mpSave(PDO $pdo, array $items, array $professional): void {
    $save = $pdo->prepare('UPDATE profissionais SET marketplace_products = :products WHERE id = :id AND user_id = :user_id');
    $save->execute([':products'=>json_encode(array_values($items), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), ':id'=>(int)$professional['id'], ':user_id'=>(int)currentUserId()]);
}

$csrf = ensureCsrfToken(); $notice = ''; $error = ''; $items = mpItems((string)$professional['marketplace_products']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!verifyCsrfTokenOrFail($_POST['csrf_token'] ?? null)) exit;
        $action = (string)($_POST['action'] ?? ''); $id = (string)($_POST['id'] ?? '');
        $index = array_search($id, array_column($items, 'id'), true);
        if ($action === 'reorder') {
            $ids = json_decode((string)($_POST['order'] ?? '[]'), true); if (!is_array($ids)) throw new RuntimeException('Ordem inválida.');
            $byId = array_column($items, null, 'id'); $ordered = [];
            foreach ($ids as $wanted) if (is_string($wanted) && isset($byId[$wanted])) { $ordered[] = $byId[$wanted]; unset($byId[$wanted]); }
            foreach ($byId as $item) $ordered[] = $item; foreach ($ordered as $i => &$item) $item['order'] = $i; unset($item); $items = $ordered; $notice = 'Nova ordem salva.';
        } elseif ($action === 'delete' && $index !== false) { array_splice($items, $index, 1); $notice = 'Produto excluído.'; }
        elseif ($action === 'toggle' && $index !== false) { $items[$index]['active'] = !$items[$index]['active']; $notice = 'Status atualizado.'; }
        elseif ($action === 'save') {
            $title = mb_substr(trim((string)($_POST['title'] ?? '')), 0, 100); $description = mb_substr(trim((string)($_POST['description'] ?? '')), 0, 60); $price = mb_substr(trim((string)($_POST['price'] ?? '')), 0, 40);
            if ($title === '') throw new RuntimeException('Informe o nome do produto.');
            $existing = $index !== false ? $items[$index] : null;
            $images = $existing['images'] ?? [];
            foreach ((array)($_POST['remove_images'] ?? []) as $remove) { $images = array_values(array_filter($images, static fn($image) => $image !== $remove)); }
            foreach ((array)($_FILES['images']['name'] ?? []) as $key => $_) { if (($_FILES['images']['error'][$key] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) $images[] = mpUpload(['name'=>$_FILES['images']['name'][$key], 'type'=>$_FILES['images']['type'][$key], 'tmp_name'=>$_FILES['images']['tmp_name'][$key], 'error'=>$_FILES['images']['error'][$key], 'size'=>$_FILES['images']['size'][$key]]); }
            $images = array_slice($images, 0, 4);
            if (!$existing && !$images) throw new RuntimeException('A primeira foto é obrigatória para um novo produto.');
            $record = ['id'=>$existing['id'] ?? bin2hex(random_bytes(12)), 'title'=>$title, 'description'=>$description, 'price'=>$price, 'active'=>isset($_POST['active']), 'images'=>$images, 'order'=>$existing['order'] ?? count($items)];
            if ($index === false) { if (count($items) >= 20) throw new RuntimeException('O limite é de 20 produtos.'); $items[] = $record; $notice = 'Produto adicionado.'; } else { $items[$index] = $record; $notice = 'Produto atualizado.'; }
        } else throw new RuntimeException('Ação inválida.');
        foreach ($items as $i => &$item) $item['order'] = $i; unset($item); mpSave($pdo, $items, $professional);
    } catch (RuntimeException $e) { $error = $e->getMessage(); }
}
