<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mini marketplace</title><script src="https://cdn.tailwindcss.com"></script><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>
 body{font-family:Inter,sans-serif;background:linear-gradient(180deg,#f8fbff 0%,#f1f5fb 100%)}.side{background:linear-gradient(160deg,#082d59,#123e70)}@media(min-width:1024px){.side{position:sticky;top:0;height:100vh;align-self:start}}@media(max-width:1023px){.side{display:flex!important;position:sticky;top:0;z-index:40;min-height:0;padding:.6rem .5rem}.side>a:first-child,.side>.mt-auto{display:none}.side nav{display:flex;flex:1;gap:.2rem;margin:0}.side nav p{display:none}.side nav>a{flex:1;min-width:0;overflow:hidden;padding:.68rem .2rem;text-align:center;font-size:0;white-space:nowrap}.side nav>a:before{font-size:.72rem;font-weight:700}.side nav>a:nth-of-type(1):before{content:"Agenda"}.side nav>a:nth-of-type(2):before{content:"Loja"}.side nav>a:nth-of-type(3):before{content:"Conta"}.side nav>*+*{margin-top:0!important}}.dragging{opacity:.45}.drop-target{outline:2px dashed #2563eb}.modal{display:none}.modal.open{display:flex}.modal-card{animation:modalIn .18s ease-out}@keyframes modalIn{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}.field-label{display:block;font-size:.83rem;font-weight:700;color:#334155}.field-control{margin-top:.45rem;width:100%;border:1px solid #d7e0eb;border-radius:.75rem;background:#fff;padding:.72rem .85rem;font-size:.92rem;color:#0f172a;transition:border-color .15s,box-shadow .15s}.field-control:focus{outline:0;border-color:#2563eb;box-shadow:0 0 0 3px #dbeafe}.upload-zone{border:1.5px dashed #93c5fd;border-radius:1rem;background:#f8fbff;padding:1rem;transition:.15s}.upload-zone:hover{border-color:#2563eb;background:#eff6ff}.preview-card{position:relative;overflow:hidden;border-radius:.7rem;border:1px solid #dbe4f0;background:#fff}.preview-card img{height:72px;width:100%;object-fit:cover}.modal-close{display:inline-flex;height:2.25rem;width:2.25rem;align-items:center;justify-content:center;border-radius:.65rem;color:#64748b;font-size:1.5rem;line-height:1}.modal-close:hover{background:#f1