</style></head><body class="min-h-screen text-slate-900"><div class="grid min-h-screen lg:grid-cols-[300px_1fr]"><aside class="side hidden lg:flex flex-col p-6 text-white"><a href="<?=htmlspecialchars(appPath('/access/painel.php'),ENT_QUOTES,'UTF-8')?>" class="flex items-center gap-3 border-b border-white/10 px-2 pb-6 font-extrabold"><img src="../img/logomenor.png" class="h-8 w-8" alt="">Clube dos Parceiros</a><nav class="mt-7 space-y-1"><p class="mb-3 px-2 text-[10px] font-bold text-blue-200">CONFIGURAÇÕES</p><a href="<?=htmlspecialchars(appPath('/access/configurar_agenda.php'),ENT_QUOTES,'UTF-8')?>" class="block rounded-lg px-3 py-3 text-sm font-semibold text-blue-100 hover:bg-white/10">Agendamentos</a><a href="<?=htmlspecialchars(appPath('/access/mini_marketplace.php'),ENT_QUOTES,'UTF-8')?>" class="block rounded-lg bg-blue-600 px-3 py-3 text-sm font-bold">Mini marketplace</a><a href="<?=htmlspecialchars(appPath('/secure/conta.php'),ENT_QUOTES,'UTF-8')?>" class="block rounded-lg px-3 py-3 text-sm font-semibold text-blue-100 hover:bg-white/10">Conta</a></nav></aside><main class="mx-auto w-full max-w-6xl px-5 py-8 sm:px-8"><div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-extrabold">Mini marketplace</h1><p class="mt-1 text-sm text-slate-500">Cadastre até 20 produtos ou serviços para aparecerem no seu perfil público.</p></div><button id="addProduct" class="rounded-xl bg-blue-700 px-5 py-3 text-sm font-bold text-white hover:bg-blue-800">+ Adicionar produto</button></div><?php if($notice):?><p class="mt-5 rounded-lg bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-700"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></p><?php endif;?><?php if($error):?><p class="mt-5 rounded-lg bg-red-50 px-4 py-3 text-sm font-semibold text-red-700"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><div class="mt-7 flex flex-col gap-3 sm:flex-row"><input id="search" class="rounded-xl border border-slate-300 px-4 py-2.5 text-sm" placeholder="Buscar por nome ou descrição"><div class="flex gap-2"><button data-filter="all" class="filter rounded-lg bg-blue-700 px-4 py-2 text-sm font-semibold text-white">Todos</button><button data-filter="active" class="filter rounded-lg border px-4 py-2 text-sm font-semibold">Ativos</button><button data-filter="inactive" class="filter rounded-lg border px-4 py-2 text-sm font-semibold">Inativos</button></div></div><p class="mt-4 text-xs text-slate-500">Arraste os cards para alterar a ordem pública.</p><div id="cards" class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"></div><div id="empty" class="mt-6 hidden rounded-xl border border-dashed p-8 text-center text-slate-500">Nenhum produto encontrado.</div><div id="pagination" class="mt-6 flex gap-2"></div></main></div>
<div id="modal" class="modal fixed inset-0 z-50 items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm"><form id="productForm" method="post" enctype="multipart/form-data" class="modal-card max-h-[92vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white shadow-2xl"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="save"><input id="productId" type="hidden" name="id"><header class="flex items-center justify-between border-b border-slate-100 px-6 py-5"><div><p class="text-xs font-extrabold uppercase tracking-[.14em] text-blue-600">Mini marketplace</p><h2 id="modalTitle" class="mt-1 text-xl font-extrabold text-slate-900">Adicionar produto</h2><p class="mt-1 text-sm text-slate-500">Preencha as informações que aparecerão no seu perfil.</p></div><button type="button" class="close modal-close" aria-label="Fechar">×</button></header><div class="space-y-5 px-6 py-6"><div class="grid gap-5 md:grid-cols-2"><label class="field-label md:col-span-2">Nome do produto<input id="title" name="title" required maxlength="100" class="field-control" placeholder="Ex.: Limpeza de ar-condicionado"></label><label class="field-label">Descrição curta <span class="font-medium text-slate-400">(até 60 caracteres)</span><textarea id="description" name="description" maxlength="60" rows="3" class="field-control resize-none" placeholder="Descreva rapidamente o produto ou serviço"></textarea></label><label class="field-label">Preço “a partir de”<input id="price" name="price" maxlength="40" class="field-control" placeholder="Ex.: R$ 99,00"></label></div><label class="flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700"><input id="active" type="checkbox" name="active" checked class="h-4 w-4 rounded border-slate-300 text-blue-700 focus:ring-blue-500"><span>Produto ativo</span><span class="ml-auto text-xs font-medium text-slate-400">Visível no perfil público</span></label><section class="upload-zone"><div class="flex flex-wrap items-start justify-between gap-2"><div><h3 class="text-sm font-bold text-slate-800">Fotos do produto</h3><p class="mt-1 text-xs text-slate-500">Até 4 imagens em JPG, PNG ou WEBP. A primeira é obrigatória ao criar.</p></div><span class="rounded-full bg-blue-100 px-2.5 py-1 text-xs font-bold text-blue-700">Máx. 4 fotos</span></div><label class="mt-4 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-blue-200 bg-white px-4 py-3 text-sm font-bold text-blue-700 hover:bg-blue-50"><span class="text-lg">+</span> Selecionar fotos<input id="images" name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple class="sr-only"></label><div id="previews" class="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"></div></section></div><footer class="flex items-center justify-end gap-3 border-t border-slate-100 bg-slate-50 px-6 py-4"><button type="button" class="close rounded-xl px-4 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-200">Cancelar</button><button class="rounded-xl bg-blue-700 px-5 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-blue-800">Salvar produto</button></footer></form></div><form id="actionForm" method="post" class="hidden"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input name="action"><input name="id"><input name="order"></form><script id="items-data" type="application/json"><?=htmlspecialchars(json_encode($items,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_NOQUOTES,'UTF-8')?></script><script>
const items=JSON.parse(document.querySelector('#items-data').textContent),cards=document.querySelector('#cards'),modal=document.querySelector('#modal'),form=document.querySelector('#productForm'),actionForm=document.querySelector('#actionForm');let filter='all',page=1,dragId=null,editing=null;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function submitAction(action,id='',order=''){actionForm.querySelector('[name=action]').value=action;actionForm.querySelector('[name=id]').value=id;actionForm.querySelector('[name=order]').value=order;actionForm.submit()}
function matches(x){const q=document.querySelector('#search').value.toLowerCase();return (filter==='all'||(filter==='active')===!!x.active)&&(!q||(x.title+' '+x.description).toLowerCase().includes(q))}
function render(){let found=items.filter(matches),start=(page-1)*5,shown=found.slice(start,start+5);if(start>=found.length&&page>1){page--;return render()}cards.innerHTML=shown.map(x=>`<article draggable="true" data-id="${x.id}" class="card overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="relative h-40 bg-slate-100">${x.images[0]?`<img src="${esc(x.images[0])}" class="h-full w-full object-cover">`:'<div class="flex h-full items-center justify-center text-slate-400">Sem foto</div>'}<span class="absolute right-3 top-3 rounded-full px-2 py-1 text-xs font-bold ${x.active?'bg-emerald-100 text-emerald-700':'bg-slate-200 text-slate-600'}">${x.active?'Ativo':'Inativo'}</span></div><div class="p-4"><h3 class="font-extrabold">${esc(x.title)}</h3><p class="mt-1 min-h-10 text-sm text-slate-500">${esc(x.description)}</p><p class="mt-3 font-bold text-blue-700">${x.price?'A partir de '+esc(x.price):'Preço a combinar'}</p><div class="mt-4 flex gap-2"><button class="edit rounded-lg border px-3 py-2 text-sm font-bold" data-id="${x.id}">Editar</button><button class="toggle rounded-lg border px-3 py-2 text-sm font-bold" data-id="${x.id}">${x.active?'Desativar':'Ativar'}</button><button class="delete ml-auto rounded-lg px-2 py-2 text-red-600" data-id="${x.id}" title="Excluir">⋮</button></div></div></article>`).join('');document.querySelector('#empty').classList.toggle('hidden',!!found.length);document.querySelector('#pagination').innerHTML=Array.from({length:Math.ceil(found.length/5)},(_,i)=>`<button data-page="${i+1}" class="rounded px-3 py-1 ${page===i+1?'bg-blue-700 text-white':'border'}">${i+1}</button>`).join('')}
function open(item){editing=item||null;form.reset();document.querySelector('#modalTitle').textContent=item?'Editar produto':'Adicionar produto';productId.value=item?.id||'';title.value=item?.title||'';description.value=item?.description||'';price.value=item?.price||'';active.checked=item?item.active:true;drawPreviews(item?.images||[]);modal.classList.add('open')}
function drawPreviews(images){previews.innerHTML=images.map(url=>`<label class="preview-card"><img src="${esc(url)}"><input type="checkbox" name="remove_images[]" value="${esc(url)}" class="absolute left-1 top-1"> <span class="text-xs">Remover</span></label>`).join('')}
addProduct.onclick=()=>{if(items.length>=20)return alert('Você já atingiu o limite de 20 produtos.');open()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>modal.classList.remove('open'));images.onchange=()=>{let keep=editing?.images||[],files=[...images.files];if(keep.length+files.length>4){alert('Use no máximo 4 fotos.');images.value='';return}drawPreviews(keep);files.forEach(f=>{let u=URL.createObjectURL(f);previews.insertAdjacentHTML('beforeend',`<div class="preview-card"><img src="${u}"></div>`)})};search.oninput=()=>{page=1;render()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;document.querySelectorAll('.filter').forEach(x=>x.className='filter rounded-lg border px-4 py-2 text-sm font-semibold');b.className='filter rounded-lg bg-blue-700 px-4 py-2 text-sm font-semibold text-white';render()});cards.onclick=e=>{let id=e.target.dataset.id;if(e.target.classList.contains('edit'))open(items.find(x=>x.id===id));if(e.target.classList.contains('toggle'))submitAction('toggle',id);if(e.target.classList.contains('delete')&&confirm('Excluir este produto?'))submitAction('delete',id)};document.querySelector('#pagination').onclick=e=>{if(e.target.dataset.page){page=+e.target.dataset.page;render()}};cards.addEventListener('dragstart',e=>{dragId=e.target.closest('.card')?.dataset.id;e.target.closest('.card')?.classList.add('dragging')});cards.addEventListener('dragover',e=>e.preventDefault());cards.addEventListener('drop',e=>{e.preventDefault();let target=e.target.closest('.card')?.dataset.id;if(!target||target===dragId)return;let a=items.findIndex(x=>x.id===dragId),b=items.findIndex(x=>x.id===target);items.splice(b,0,items.splice(a,1)[0]);submitAction('reorder','',JSON.stringify(items.map(x=>x.id)))});cards.addEventListener('dragend',()=>document.querySelectorAll('.dragging').forEach(x=>x.classList.remove('dragging')));render();
</script><script>
(() => {
